"""Build a resumable, scoped acquisition report from current inventory fragments."""
from pathlib import Path
import json,hashlib,shutil
R=Path(__file__).resolve().parents[1];D=R/'asset_library/manifests/acquisition_20261019'
rd=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
rows=rd(D/'inventory.json');new=[r for r in rows if r['record_scope'].startswith('2026')]
checks=[]; hashes={}
for r in new:
 paths=[]
 for f in r.get('files',[]):
  p=f.get('path',f.get('local_file_path')); h=f.get('sha256')
  if p:paths.append((p,h))
 p=r.get('converted_file') or r.get('file')
 if isinstance(p,str):paths.append((p,r.get('converted_sha256') or r.get('sha256')))
 if isinstance(r.get('local_file_path'),str) and (R/r['local_file_path']).is_file():
  paths.append((r['local_file_path'],r.get('sha256') if isinstance(r.get('sha256'),str) else None))
 for p,h in paths:
  f=R/p; actual=hashlib.sha256(f.read_bytes()).hexdigest() if f.is_file() else None
  checks.append({'asset_id':r['asset_id'],'path':p,'exists':f.is_file(),'sha256':actual,'recorded_hash_match':actual==h if h else None})
  if actual:hashes.setdefault(actual,set()).add(p)
(D/'final_file_checks.json').write_text(json.dumps({'scope':'Current listed payloads only; historical checks preserved separately','checks':checks,'duplicate_content_paths':{h:sorted(v) for h,v in hashes.items() if len(v)>1}},indent=2))
